// The identifiers of the deployment under drill.
const (
	clinicApplication = "clinic-booking"
	deploymentID      = "dep_dr_drill"
	// audience is what the clinic's context exchange (alixai.yaml) says its tokens carry.
	audience = "alixai"
	// auditSignerID is the platform key that signs integration-audit reports. It is generated by
	// the test: `alixai audit run` refuses the published TEST-ONLY key for that role.
	auditSignerID = "dr-drill-audit-signer"
	drillOperator = "dr-drill-operator"
	clinicPkgRel  = "examples/reference-apps/clinic-booking/package"
	signedAtOfPkg = "2026-10-01T00:00:00Z"
	signExpires   = "2036-10-01T00:00:00Z"
)

// env is everything the scenarios share, built once per test binary: the built programs, the
// application and its proxy, and the golden data directory every scenario copies. Building it
// takes about a minute (an integration audit against the real application, twice), so a scenario
// that built its own would not fit the ten minutes `go test` allows.
type env struct {
	root       string
	moduleRoot string
	bin        string // the built alixai
	releaseBin string // the built tools/release
	clinic     *clinicApp
	proxy      *mcpProxy
	goldenRoot string
	// signerKey is the private half of the audit report signer, kept outside every data directory.
	signerKey string
	// releaseManifest is a release manifest signed with the published TEST-ONLY key, for
	// `alixai upgrade apply -allow-dev-key`.
	releaseManifest string

	buildDur  time.Duration
	goldenDur time.Duration
}

var shared struct {
	once sync.Once
	e    *env
	err  error
}

// sharedEnv returns the environment, building it on first use. A failure fails every scenario with
// the same message.
func sharedEnv(t *testing.T) *env {
	t.Helper()
	shared.once.Do(func() { shared.e, shared.err = newEnv() })
	if shared.err != nil {
		t.Fatalf("the drill environment could not be built: %v", shared.err)
	}
	if !shared.e.clinic.alive() {
		t.Fatal("the clinic application subprocess has exited")
	}
	return shared.e
}

func TestMain(m *testing.M) {
	code := m.Run()
	if shared.e != nil {
		shared.e.close()
	}
	if dir := os.Getenv("ALIXAI_DR_EVIDENCE_DIR"); dir != "" && code == 0 {
		// A relative directory is relative to the repository root, where the drill is run from by
		// hand: `go test` itself runs in tests/dr.
		if !filepath.IsAbs(dir) {
			dir = filepath.Join("..", "..", dir)
		}
		if err := writeEvidence(dir); err != nil {
			fmt.Fprintf(os.Stderr, "dr: the evidence could not be written: %v\n", err)
			code = 1
		}
	}
	os.Exit(code)
}

func newEnv() (e *env, err error) {
	e = &env{}
	defer func() {
		if err != nil {
			e.close()
		}
	}()
	if e.moduleRoot, err = filepath.Abs("../.."); err != nil {
		return e, err
	}
	if _, err = os.Stat(filepath.Join(e.moduleRoot, "go.mod")); err != nil {
		return e, fmt.Errorf("the module root is not two directories above the test: %w", err)
	}
	if e.root, err = os.MkdirTemp("", "alixai-dr-"); err != nil {
		return e, err
	}

	begin := time.Now()
	binDir := filepath.Join(e.root, "bin")
	if err = os.MkdirAll(binDir, 0o700); err != nil {
		return e, err
	}
	e.bin = filepath.Join(binDir, "alixai"+exeSuffix())
	e.releaseBin = filepath.Join(binDir, "release"+exeSuffix())
	if err = goBuild(e.moduleRoot, e.bin, "./cmd/alixai"); err != nil {
		return e, err
	}
	if err = goBuild(e.moduleRoot, e.releaseBin, "./tools/release"); err != nil {
		return e, err
	}
	e.buildDur = time.Since(begin)

	if e.clinic, err = startClinic(e.moduleRoot); err != nil {
		return e, err
	}
	if e.proxy, err = startProxy(e.clinic.mcpURL); err != nil {
		return e, err
	}

	begin = time.Now()
	if err = e.buildGolden(); err != nil {
		return e, err
	}
	e.goldenDur = time.Since(begin)
	if err = e.buildReleaseManifest(); err != nil {
		return e, err
	}
	e.recordEnvironment()
	return e, nil
}

// recordEnvironment writes what the evidence report says about the machine and the build.
func (e *env) recordEnvironment() {
	recordEnv("Host", fmt.Sprintf("%s/%s, %d logical CPUs, an emulated dev box (not a certified profile)", runtime.GOOS, runtime.GOARCH, runtime.NumCPU()))
	recordEnv("Go", runtime.Version())
	if r := execProgram(30*time.Second, e.moduleRoot, "node", "--version"); r.Code == 0 {
		recordEnv("Node (the clinic application)", strings.TrimSpace(r.Stdout))
	}
	if fi, err := os.Stat(e.bin); err == nil {
		recordEnv("alixai binary", fmt.Sprintf("%.1f MiB, CGO_ENABLED=0, version %s", float64(fi.Size())/(1<<20), versionOf(e)))
	}
	recordEnv("Build of alixai and tools/release", e.buildDur.Round(100*time.Millisecond).String()+" (warm module and build cache)")
	recordEnv("Golden deployment", e.goldenDur.Round(100*time.Millisecond).String()+": sign and install the clinic package, then the integration audit twice against the running application")
	if fi, err := os.Stat(filepath.Join(e.goldenRoot, "data", "alixai.db")); err == nil {
		recordEnv("Database of a fresh deployment", fmt.Sprintf("%.0f KiB", float64(fi.Size())/1024))
	}
}

func versionOf(e *env) string {
	r := execProgram(30*time.Second, e.moduleRoot, e.bin, "version")
	return strings.Join(strings.Fields(r.Stdout), " ")
}

// close stops what the environment started (only those processes) and removes its files.
func (e *env) close() {
	if e.proxy != nil {
		e.proxy.stop()
	}
	if e.clinic != nil {
		e.clinic.stop()
	}
	if e.root != "" {
		_ = os.RemoveAll(e.root)
	}
}

func exeSuffix() string {
	if runtime.GOOS == "windows" {
		return ".exe"
	}
	return ""
}

// goTool finds the go command: the test binary does not inherit a PATH entry for it.
func goTool() string {
	if p, err := exec.LookPath("go"); err == nil {
		return p
	}
	return filepath.Join(runtime.GOROOT(), "bin", "go"+exeSuffix())
}

func goBuild(moduleRoot, out, pkg string) error {
	cmd := exec.Command(goTool(), "build", "-trimpath", "-o", out, pkg)
	cmd.Dir = moduleRoot
	cmd.Env = append(os.Environ(), "CGO_ENABLED=0")
	if b, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("go build %s: %w\n%s", pkg, err, b)
	}
	return nil
}

// ---- running the program ---------------------------------------------------------------------

// result is what one `alixai` command did.
type result struct {
	Code   int
	Stdout string
	Stderr string
	Dur    time.Duration
}

// cleanEnv is the environment of every subprocess: the machine's, without anything AlixAI reads, so
// a developer's own settings cannot change a drill.
func cleanEnv() []string {
	var out []string
	for _, kv := range os.Environ() {
		if strings.HasPrefix(strings.ToUpper(kv), "ALIXAI_") {
			continue
		}
		out = append(out, kv)
	}
	return out
}

// exec runs a program to completion with a time limit and reports what it did. A program that
// outlives the limit is killed: it is the process this call started.
func execProgram(limit time.Duration, dir, program string, args ...string) result {
	cmd := exec.Command(program, args...)
	cmd.Dir = dir
	cmd.Env = cleanEnv()
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	begin := time.Now()
	r := result{}
	if err := cmd.Start(); err != nil {
		r.Code, r.Stderr = -1, err.Error()
		return r
	}
	done := make(chan error, 1)
	go func() { done <- cmd.Wait() }()
	var err error
	select {
	case err = <-done:
	case <-time.After(limit):
		_ = cmd.Process.Kill()
		err = <-done
		errb.WriteString("\ndr: killed after " + limit.String())
	}
	r.Dur = time.Since(begin)
	r.Stdout, r.Stderr = out.String(), errb.String()
	var ee *exec.ExitError
	switch {
	case err == nil:
	case errors.As(err, &ee):
		r.Code = ee.ExitCode()
	default:
		r.Code = -1
	}
	return r
}

// commandWords is how many words name the command: one (`serve`, `version`) or two
// (`backup create`).
func commandWords(args []string) int {
	if len(args) > 1 && !strings.HasPrefix(args[1], "-") && args[0] != "serve" && args[0] != "version" {
		return 2
	}
	return 1
}

// run executes one command of the built binary against a configuration file. The -config flag is
// added after the command's name.
func (e *env) run(cfgPath string, args ...string) result {
	n := commandWords(args)
	full := append(append(append([]string{}, args[:n]...), "-config", cfgPath), args[n:]...)
	return execProgram(10*time.Minute, e.moduleRoot, e.bin, full...)
}

// runNoConfig executes a command that takes no configuration (`package sign`, `package keygen`).
func (e *env) runNoConfig(args ...string) result {
	return execProgram(10*time.Minute, e.moduleRoot, e.bin, args...)
}

func (r result) String() string {
	return fmt.Sprintf("exit %d after %s\nstdout:\n%s\nstderr:\n%s", r.Code, r.Dur.Round(time.Millisecond), r.Stdout, r.Stderr)
}

// decode reads the JSON a command printed.
func (r result) decode(v any) error {
	if err := json.Unmarshal([]byte(r.Stdout), v); err != nil {
		return fmt.Errorf("the output is not the JSON that was expected: %w\n%s", err, r)
	}
	return nil
}

// ---- files -------------------------------------------------------------------------------------

// freeAddr returns a loopback address that was free a moment ago.
func freeAddr() (string, error) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return "", err
	}
	defer ln.Close()
	return ln.Addr().String(), nil
}

// copyTree copies a directory tree. Files keep their content; modes are owner-only, and on
// Windows the copy's root gets an owner-only ACL that everything below inherits (a data directory
// copied under %TEMP% would otherwise inherit what %TEMP% grants, and serve refuses key files other
// users can read).
func copyTree(from, to string) error {
	if _, err := fsperm.MkdirOwnerOnly(to); err != nil {
		return err
	}
	return filepath.Walk(from, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(from, p)
		if err != nil {
			return err
		}
		dst := filepath.Join(to, rel)
		if info.IsDir() {
			return os.MkdirAll(dst, 0o700)
		}
		in, err := os.Open(p)
		if err != nil {
			return err
		}
		defer in.Close()
		out, err := os.OpenFile(dst, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
		if err != nil {
			return err
		}
		if _, err := io.Copy(out, in); err != nil {
			_ = out.Close()
			return err
		}
		return out.Close()
	})
}

// config writes the configuration of a deployment: its data directory, the address the service
// listens on, the deployment identity and the audit signer, then whatever extra YAML a scenario adds
// (another section).
func (e *env) writeConfig(path, dataDir, listen, extra string) error {
	cfg := fmt.Sprintf(`data_dir: %q
server:
  listen: %q
identity:
  deployment_id: %s
  audience: %s
integration_audit:
  signing_key_id: %s
  signing_key_file: %q
  accept_operators: [%s]
%s`, filepath.ToSlash(dataDir), listen, deploymentID, audience, auditSignerID, filepath.ToSlash(e.signerKey), drillOperator, extra)
	return os.WriteFile(path, []byte(cfg), 0o600)
}

// ---- the golden deployment ------------------------------------------------------------------

type auditFinding struct {
	Key      string `json:"key"`
	Severity string `json:"severity"`
	CheckID  string `json:"check_id"`
}

type auditRun struct {
	Outcome   string `json:"outcome"`
	Activated bool   `json:"activated"`
	Summary   struct {
		Critical int `json:"critical"`
		Warnings int `json:"warnings"`
	} `json:"summary"`
	Findings []auditFinding `json:"findings"`
}

// buildGolden does what an operator does to put the clinic application into service, with the real
// commands against a data directory: provision the report signer and the publisher key, create the
// checkpoint key, sign and install the package into quarantine, register the key the host signs
// its tokens with, run the integration audit, accept the warnings an authorised operator reviewed
// and run it again. Every scenario starts from a copy of the result.
func (e *env) buildGolden() error {
	e.goldenRoot = filepath.Join(e.root, "golden")
	dataDir := filepath.Join(e.goldenRoot, "data")
	keysDir := filepath.Join(e.root, "signer")
	pkgDir := filepath.Join(e.root, "package")
	for _, d := range []string{e.goldenRoot, keysDir} {
		if err := os.MkdirAll(d, 0o700); err != nil {
			return err
		}
	}

	// The report signer: a key the test generates with the real command, kept outside the data dir.
	if r := e.runNoConfig("package", "keygen", "-key-id", auditSignerID, "-out", keysDir); r.Code != 0 {
		return fmt.Errorf("package keygen: %s", r)
	}
	e.signerKey = filepath.Join(keysDir, auditSignerID+".key")
	signerPub := filepath.Join(keysDir, auditSignerID+".pub")
	cfg := filepath.Join(e.goldenRoot, "alixai.yaml")
	if err := e.writeConfig(cfg, dataDir, "127.0.0.1:0", ""); err != nil {
		return err
	}

	// The package: the clinic's own, its one endpoint (and the egress entry that allows exactly it)
	// pointed at the proxy, signed again with the published TEST-ONLY publisher key.
	if err := copyTree(filepath.Join(e.moduleRoot, filepath.FromSlash(clinicPkgRel)), pkgDir); err != nil {
		return err
	}
	if err := retargetPackage(pkgDir, e.proxy.port); err != nil {
		return err
	}
	sign := e.runNoConfig("package", "sign", "-app", clinicApplication, "-version", "1.0.0",
		"-key", devkeys.KeyID+"="+filepath.Join(e.moduleRoot, "tools", "devkeys", "test-only-publisher.key.pem"),
		"-signed-at", signedAtOfPkg, "-expires-at", signExpires, pkgDir)
	if sign.Code != 0 {
		return fmt.Errorf("package sign: %s", sign)
	}

	steps := [][]string{
		{"trust", "add-key", "-app", "alixai.platform", "-key-id", auditSignerID, "-public-key-file", signerPub, "-operator", "root"},
		{"trust", "add-key", "-app", clinicApplication, "-key-id", devkeys.KeyID, "-public-key", devkeys.PublicKeyBase64(), "-allow-test-keys", "-operator", "root"},
		{"keys", "init"},
		{"package", "install", "-operator", "root", pkgDir},
		{"identity", "add-issuer-key", "-package", pkgDir, "-key-id", devkeys.KeyID, "-public-key", devkeys.PublicKeyBase64(), "-allow-test-key"},
	}
	for _, s := range steps {
		if r := e.run(cfg, s...); r.Code != 0 {
			return fmt.Errorf("alixai %s: %s", strings.Join(s, " "), r)
		}
	}
	return e.activate(cfg)
}

// activate runs the audit, accepts the warnings it raised and runs it again.
func (e *env) activate(cfg string) error {
	run := func() (auditRun, result, error) {
		r := e.run(cfg, "audit", "run", "-operator", drillOperator, clinicApplication)
		var out auditRun
		if strings.TrimSpace(r.Stdout) != "" {
			if err := r.decode(&out); err != nil {
				return out, r, err
			}
		}
		return out, r, nil
	}
	first, r, err := run()
	if err != nil {
		return err
	}
	if first.Summary.Critical != 0 {
		return fmt.Errorf("the clinic's audit has critical findings: %s", r)
	}
	if first.Activated {
		return nil
	}
	if first.Outcome != "needs_acceptance" {
		return fmt.Errorf("the audit neither activated the package nor asked for acceptance: %s", r)
	}
	for _, f := range first.Findings {
		if f.Severity != "warning" {
			continue
		}
		a := e.run(cfg, "audit", "accept-warning", "-finding", f.Key, "-operator", drillOperator, "-reason", "reviewed by the drill: "+f.CheckID, clinicApplication)
		if a.Code != 0 {
			return fmt.Errorf("audit accept-warning %s: %s", f.Key, a)
		}
	}
	second, r, err := run()
	if err != nil {
		return err
	}
	if !second.Activated {
		return fmt.Errorf("every warning was accepted and the package still did not activate: %s", r)
	}
	return nil
}

// retargetPackage rewrites the one port the clinic's manifest pins, in both places that name it.
func retargetPackage(dir string, port int) error {
	path := filepath.Join(dir, "alixai.yaml")
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	s := string(b)
	for _, r := range [][2]string{
		{"url: http://127.0.0.1:8787/mcp", fmt.Sprintf("url: http://127.0.0.1:%d/mcp", port)},
		{"      - 8787\n", fmt.Sprintf("      - %d\n", port)},
	} {
		if strings.Count(s, r[0]) != 1 {
			return fmt.Errorf("alixai.yaml has no single %q to retarget", r[0])
		}
		s = strings.Replace(s, r[0], r[1], 1)
	}
	return os.WriteFile(path, []byte(s), 0o600)
}

// buildReleaseManifest writes a release manifest for the built binary and signs it with the
// published TEST-ONLY key, the way `go run ./tools/release manifest` and `sign -dev-key` do for a
// release. `alixai upgrade apply` takes it with -allow-dev-key.
func (e *env) buildReleaseManifest() error {
	dir := filepath.Join(e.root, "release")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	unsigned := filepath.Join(dir, "release-manifest.unsigned.json")
	e.releaseManifest = filepath.Join(dir, "release-manifest.json")
	r := execProgram(5*time.Minute, e.moduleRoot, e.releaseBin, "manifest", "-C", e.moduleRoot,
		"-version", "1.0.0", "-commit", strings.Repeat("a", 40), "-created-at", "2026-10-03T00:00:00Z",
		"-artifact", "binary="+e.bin, "-out", unsigned)
	if r.Code != 0 {
		return fmt.Errorf("release manifest: %s", r)
	}
	r = execProgram(5*time.Minute, e.moduleRoot, e.releaseBin, "sign", "-manifest", unsigned, "-dev-key", "-out", e.releaseManifest)
	if r.Code != 0 {
		return fmt.Errorf("release sign: %s", r)
	}
	return nil
}
